1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16		"unicode/utf8"
17	)
18	
19	// Status 表示样品所处的判定状态。
20	type Status string
21	
22	const (
23		// StatusPending 样品已录入，尚未确认判定结果。
24		StatusPending Status = "pending"
25		// StatusConfirmed 样品已确认，判定结果已保存。
26		StatusConfirmed Status = "confirmed"
27		// StatusVoided 样品已作废，保留记录但不能再确认。
28		StatusVoided Status = "voided"
29	)
30	
31	var (
32		ErrClosed             = errors.New("water: 数据存放已关闭")
33		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
34		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
35		ErrUnknownPoint       = errors.New("water: 采样点未登记")
36		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
37		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
38		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
39		ErrUnknownSample      = errors.New("water: 样品编号不存在")
40		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
41		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
42		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
43		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
44		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
45		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
46		ErrInvalidText        = errors.New("water: 采样点编号、名称、项目名、样品编号或作废原因不是合法的 UTF-8 文本")
47		ErrCorruptRecord      = errors.New("water: 本地数据中存在测量项目重复或测量项目与逐项判定对应不上的损坏样品记录")
48	)
49	
50	// SamplingPoint 是按编号唯一登记的采样点。
51	type SamplingPoint struct {
52		ID   string `json:"id"`
53		Name string `json:"name"`
54	}
55	
56	// Limit 是某采样点某测量项目的一版数值上限。
57	type Limit struct {
58		PointID   string    `json:"pointId"`
59		Item      string    `json:"item"`
60		Value     float64   `json:"value"`
61		Effective time.Time `json:"effective"`
62	}
63	
64	// Measurement 是样品中一个项目的测量值。
65	type Measurement struct {
66		Item  string  `json:"item"`
67		Value float64 `json:"value"`
68	}
69	
70	// ItemResult 是确认后单个项目的判定结果。
71	type ItemResult struct {
72		Item           string    `json:"item"`
73		Value          float64   `json:"value"`
74		Limit          float64   `json:"limit"`
75		LimitEffective time.Time `json:"limitEffective"`
76		Exceeded       bool      `json:"exceeded"`
77	}
78	
79	// Sample 是一份从录入、确认到作废的样品记录。
80	type Sample struct {
81		ID           string        `json:"id"`
82		PointID      string        `json:"pointId"`
83		SampledAt    time.Time     `json:"sampledAt"`
84		Measurements []Measurement `json:"measurements"`
85		Status       Status        `json:"status"`
86		Results      []ItemResult  `json:"results,omitempty"`
87		Exceeded     bool          `json:"exceeded"`
88		VoidReason   string        `json:"voidReason,omitempty"`
89	}
90	
91	// diskState 是落盘的完整数据。
92	type diskState struct {
93		Points  map[string]SamplingPoint `json:"points"`
94		Limits  map[string][]Limit       `json:"limits"` // 键仅为落盘占位，读取时按每条限值自身的采样点与项目重新分组
95		Samples map[string]*Sample       `json:"samples"`
96	}
97	
98	// limitGroup 用两个字段各自标识一组限值，避免把包含 U+0000 的文本
99	// 用单字符拼接成键时不同组合撞成同一组。
100	type limitGroup struct {
101		pointID string
102		item    string
103	}
104	
105	// Store 是绑定到某个本地目录的取样判定数据存放。
106	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
107	type Store struct {
108		mu      sync.Mutex
109		dir     string
110		file    string
111		closed  bool
112		points  map[string]SamplingPoint
113		limits  map[limitGroup][]Limit // 按生效时间升序
114		samples map[string]*Sample
115	}
116	
117	// Open 打开（必要时创建）dir 下的本地数据存放。
118	//
119	// 读入时先核对每份样品的原测量：同一个测量项目名在一份样品里只能出现一次，
120	// 不依赖两条记录是否相邻，也不因数值相同（包括两个零）而放行；待判定样品与
121	// 待判定后作废、没有历史判定依据的样品同样适用这条规则——它们没有逐项结果
122	// 本身不是损坏，但原测量仍不允许重复。再核对每份已保存结论的样品：已确认样品，
123	// 以及已确认后作废、逐项依据仍保留在 Results 中的样品，其原测量项目与逐项判定
124	// 必须按项目名完整一一对应——至少有一个测量项目；判定里同一项目不能出现两次；
125	// 每个测量项目必须且只能有一条判定，判定里也不能出现原测量没有的项目；对应
126	// 项目的判定测量值必须与原测量值一致（零是合法测量值，不会被当成缺项）。
127	// 两个列表排列顺序不同不影响对应，成功读入后测量与判定各自保留原顺序。
128	// 任一份样品对不上，整次打开以可被 errors.Is(err, ErrCorruptRecord) 识别的
129	// 错误失败，返回 nil 数据存放，错误信息点到具体样品编号与项目；不会静默
130	// 跳过问题样品、不会择一保留或合并重复测量、不会补出缺失判定、不会把它改成
131	// 待判定，也不会改写原文件。待判定样品没有判定记录、待判定后作废的样品没有
132	// 历史依据，均属正常。完整记录原样读入，已保存的上限、生效时间、逐项结论与
133	// 整份超标标记保留，不因后来新增或补录的限值而拒绝或重新计算。
134	func Open(dir string) (*Store, error) {
135		if strings.TrimSpace(dir) == "" {
136			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
137		}
138		if err := os.MkdirAll(dir, 0o755); err != nil {
139			return nil, err
140		}
141		s := &Store{
142			dir:     dir,
143			file:    filepath.Join(dir, "water-data.json"),
144			points:  map[string]SamplingPoint{},
145			limits:  map[limitGroup][]Limit{},
146			samples: map[string]*Sample{},
147		}
148		data, err := os.ReadFile(s.file)
149		if errors.Is(err, fs.ErrNotExist) {
150			return s, nil
151		}
152		if err != nil {
153			return nil, err
154		}
155		var st diskState
156		if err := json.Unmarshal(data, &st); err != nil {
157			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
158		}
159		if st.Points != nil {
160			s.points = st.Points
161		}
162		if st.Limits != nil {
163			// 不按落盘键分组：键可能是旧版本用单字符拼接生成的，包含 U+0000 的
164			// 不同（采样点，项目）组合会共用同一个键。以每条限值自身的两个字段为准，
165			// 让曾经被错误合并的组在重新打开时也能各自归位。
166			for _, versions := range st.Limits {
167				for _, lim := range versions {
168					g := limitGroup{pointID: lim.PointID, item: lim.Item}
169					s.limits[g] = append(s.limits[g], lim)
170				}
171			}
172			for g, versions := range s.limits {
173				sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
174				s.limits[g] = versions
175			}
176		}
177		if st.Samples != nil {
178			// 逐份校验后才整体接收：原测量项目名重复对任何状态的样品都是损坏，
179			// 带结论的样品还要求逐项判定与原测量完整对应。任一份样品不通过，
180			// 整次打开都失败，不返回数据存放对象，也不静默跳过、择一保留、
181			// 补判定或回写原文件。
182			ids := make([]string, 0, len(st.Samples))
183			for id := range st.Samples {
184				ids = append(ids, id)
185			}
186			sort.Strings(ids)
187			for _, id := range ids {
188				if err := validateLoadedSample(id, st.Samples[id]); err != nil {
189					return nil, err
190				}
191			}
192			s.samples = st.Samples
193		}
194		return s, nil
195	}
196	
197	// validateLoadedSample 校验一份从本地文件读入的样品记录。
198	//
199	// 无论样品处于什么状态，原测量项目名都不允许重复：同一个项目名在 Measurements
200	// 中只能出现一次，按文件中保存的完整项目名判断，不依赖两条记录是否相邻，也不因
201	// 数值相同（含两个零）而放行。因此待判定样品与待判定后作废（Results 为空、没有
202	// 历史判定依据）的样品虽然没有逐项结果，仍要过这一关；它们没有判定记录本身不是
203	// 损坏，测量项目不重复即正常读入，不会被要求已经有判定依据。
204	//
205	// 带结论的样品还要满足：已确认样品，以及已确认后作废、Results 中仍保留历史依据
206	// 的样品，其原测量项目与逐项判定必须按项目名一一对应——至少一个测量项目；判定中
207	// 同一项目不能出现两次；每个测量项目必须且只能有一条判定记录，判定中也不能出现
208	// 原测量没有的项目；对应项目的判定测量值必须与原测量值逐位一致（零是合法测量值，
209	// 按 map 中是否存在该项目判断，不把零当成缺项）。项目按名称对应，与两个列表的
210	// 排列顺序无关。key 是落盘 map 中的样品编号，用于在记录本身残缺（如空记录）时
211	// 仍能指出是哪份样品。
212	func validateLoadedSample(key string, smp *Sample) error {
213		if smp == nil {
214			return fmt.Errorf("%w: 样品 %s 的记录为空", ErrCorruptRecord, key)
215		}
216		id := smp.ID
217		if id == "" {
218			id = key
219		}
220		// 原测量项目名去重适用于任何状态的样品（含待判定、待判定后作废）：
221		// 重复测量是记录本身损坏，不能等确认保存判定依据时才暴露。
222		meas := make(map[string]float64, len(smp.Measurements))
223		for _, m := range smp.Measurements {
224			if _, ok := meas[m.Item]; ok {
225				return fmt.Errorf("%w: 样品 %s 的测量项目 %s 重复", ErrCorruptRecord, id, m.Item)
226			}
227			meas[m.Item] = m.Value
228		}
229		// 待判定样品与待判定后作废（没有历史依据）的样品没有逐项判定，
230		// 原测量不重复即为正常记录，不要求它们已经有结论。
231		if smp.Status != StatusConfirmed && len(smp.Results) == 0 {
232			return nil
233		}
234		if len(smp.Measurements) == 0 {
235			return fmt.Errorf("%w: 样品 %s 没有测量项目", ErrCorruptRecord, id)
236		}
237		got := make(map[string]float64, len(smp.Results))
238		for _, r := range smp.Results {
239			if _, ok := got[r.Item]; ok {
240				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定记录重复", ErrCorruptRecord, id, r.Item)
241			}
242			got[r.Item] = r.Value
243		}
244		// 缺项或判定测量值与原测量不一致（按测量列表顺序报告，保持信息稳定）。
245		for _, m := range smp.Measurements {
246			rv, ok := got[m.Item]
247			if !ok {
248				return fmt.Errorf("%w: 样品 %s 缺少项目 %s 的判定记录", ErrCorruptRecord, id, m.Item)
249			}
250			if rv != m.Value {
251				return fmt.Errorf("%w: 样品 %s 的项目 %s 判定测量值 %g 与原测量值 %g 不一致",
252					ErrCorruptRecord, id, m.Item, rv, m.Value)
253			}
254		}
255		// 判定中出现原测量没有的项目。
256		for _, r := range smp.Results {
257			if _, ok := meas[r.Item]; !ok {
258				return fmt.Errorf("%w: 样品 %s 的判定记录出现了原测量中没有的项目 %s",
259					ErrCorruptRecord, id, r.Item)
260			}
261		}
262		return nil
263	}
264	
265	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
266	func (s *Store) Close() error {
267		s.mu.Lock()
268		defer s.mu.Unlock()
269		if s.closed {
270			return nil
271		}
272		s.closed = true
273		return nil
274	}
275	
276	func clean(s string) string { return strings.TrimSpace(s) }
277	
278	// diskLimitKey 生成仅用于落盘 JSON 的分组键。带上两个字段的长度前缀，
279	// 任何包含 U+0000 的文本组合都不会撞键；读取时并不依赖该键分组。
280	func diskLimitKey(pointID, item string) string {
281		return strconv.Itoa(len(pointID)) + ":" + pointID + strconv.Itoa(len(item)) + ":" + item
282	}
283	
284	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
285	
286	// invalidUTF8 报告文本是否无法作为合法 UTF-8 原样保存。必须在任何处理之前检查
287	// 提交的原始文本：落盘 JSON 会把非法字节（孤立的 0xFF、0xFE、不完整的多字节
288	// 序列等）静默替换成 U+FFFD，返回记录与保存内容会因此对不上，两个不同编号也
289	// 可能变成同一文本。真正的 U+FFFD（“�”）以及中文、U+0000 等都是合法字符，
290	// 不在拒绝之列；只在去首尾空白之外不做任何字符替换或归一化。
291	func invalidUTF8(s string) bool { return !utf8.ValidString(s) }
292	
293	func (s *Store) checkOpenLocked() error {
294		if s.closed {
295			return ErrClosed
296		}
297		return nil
298	}
299	
300	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
301	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
302	func (s *Store) persistLocked() error {
303		diskLimits := make(map[string][]Limit, len(s.limits))
304		for g, versions := range s.limits {
305			diskLimits[diskLimitKey(g.pointID, g.item)] = versions
306		}
307		data, err := json.MarshalIndent(diskState{
308			Points:  s.points,
309			Limits:  diskLimits,
310			Samples: s.samples,
311		}, "", "  ")
312		if err != nil {
313			return err
314		}
315		tmp := s.file + ".tmp"
316		if err := os.WriteFile(tmp, data, 0o644); err != nil {
317			return err
318		}
319		return os.Rename(tmp, s.file)
320	}
321	
322	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
323	// 保存和比较均使用处理后的文本；重复编号拒绝。
324	// 编号和名称必须都是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE 字节
325	// 或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
326	// 拒绝，不占用编号、不改动任何已有采样点；即使另一项为空白，或编号已登记而
327	// 这次名称含非法字节，也报告编码错误。真正的 U+FFFD（“�”）、中文和文本内部
328	// 的 U+0000 仍是合法字符。
329	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
330		s.mu.Lock()
331		defer s.mu.Unlock()
332		if err := s.checkOpenLocked(); err != nil {
333			return SamplingPoint{}, err
334		}
335		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
336		// 静默替换成 U+FFFD，登记“成功”后保存的编号或名称就会与填写内容对不上，
337		// 两个不同编号（如末尾分别带孤立 0xFF、0xFE）还可能保存成同一编号；
338		// 只有整次拒绝才能保证采样点身份在保存前后一致。
339		if invalidUTF8(id) || invalidUTF8(name) {
340			return SamplingPoint{}, ErrInvalidText
341		}
342		id, name = clean(id), clean(name)
343		if id == "" || name == "" {
344			return SamplingPoint{}, ErrEmptyField
345		}
346		if _, ok := s.points[id]; ok {
347			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
348		}
349		p := SamplingPoint{ID: id, Name: name}
350		s.points[id] = p
351		if err := s.persistLocked(); err != nil {
352			delete(s.points, id)
353			return SamplingPoint{}, err
354		}
355		return p, nil
356	}
357	
358	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
359	// 采样点编号和项目名必须是合法的 UTF-8 文本：任一字段含孤立的 0xFF、0xFE
360	// 字节或不完整的多字节序列等无法原样保存的内容时，整次登记以 ErrInvalidText
361	// 拒绝，不新增版本、不占用生效时间；真正的 U+FFFD（“�”）、中文和文本内部的
362	// U+0000 仍是合法字符。即使同次请求还存在采样点未登记、数值不是有限数或
363	// 生效时间缺失的问题，也报告文本编码错误。
364	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
365	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
366		s.mu.Lock()
367		defer s.mu.Unlock()
368		if err := s.checkOpenLocked(); err != nil {
369			return Limit{}, err
370		}
371		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
372		// 静默替换成 U+FFFD，登记“成功”后保存的项目名就会与填写内容对不上，
373		// 限值也不再属于实际填写的采样点和项目；只有整次拒绝才能保证一致。
374		if invalidUTF8(pointID) || invalidUTF8(item) {
375			return Limit{}, ErrInvalidText
376		}
377		pointID, item = clean(pointID), clean(item)
378		if pointID == "" || item == "" {
379			return Limit{}, ErrEmptyField
380		}
381		if _, ok := s.points[pointID]; !ok {
382			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
383		}
384		if !finite(value) {
385			return Limit{}, ErrInvalidValue
386		}
387		if effective.IsZero() {
388			return Limit{}, ErrInvalidTime
389		}
390		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
391		g := limitGroup{pointID: pointID, item: item}
392		versions := s.limits[g]
393		for _, v := range versions {
394			if v.Effective.Equal(lim.Effective) {
395				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
396			}
397		}
398		old := s.limits[g]
399		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
400		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
401		versions = make([]Limit, len(old)+1)
402		copy(versions, old)
403		versions[len(old)] = lim
404		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
405		s.limits[g] = versions
406		if err := s.persistLocked(); err != nil {
407			s.limits[g] = old
408			return Limit{}, err
409		}
410		return lim, nil
411	}
412	
413	// SubmitSample 录入一份样品，初始为待判定状态。
414	// 样品编号、采样点编号和每个项目名必须是合法的 UTF-8 文本：任一字段含孤立的
415	// 0xFF、0xFE 字节或不完整的多字节序列等无法原样保存的内容时，整份提交以
416	// ErrInvalidText 拒绝，不留部分记录，也不占用编号；真正的 U+FFFD（“�”）
417	// 仍是合法字符。再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
418	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
419	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
420		s.mu.Lock()
421		defer s.mu.Unlock()
422		if err := s.checkOpenLocked(); err != nil {
423			return Sample{}, err
424		}
425		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
426		// 静默替换成 U+FFFD，只有整份拒绝才能保证返回记录、按点查看与保存数据一致。
427		// 即使编号已被已有样品占用、非法项目排在最后，或提交同时存在其它内容问题，
428		// 也必须报告编码问题：不能归为未知采样点、项目重复或同编号冲突，更不能走
429		// 重复录入成功的分支。
430		if invalidUTF8(id) || invalidUTF8(pointID) {
431			return Sample{}, ErrInvalidText
432		}
433		for _, m := range measurements {
434			if invalidUTF8(m.Item) {
435				return Sample{}, ErrInvalidText
436			}
437		}
438		id, pointID = clean(id), clean(pointID)
439		if id == "" || pointID == "" {
440			return Sample{}, ErrEmptyField
441		}
442		if sampledAt.IsZero() {
443			return Sample{}, ErrInvalidTime
444		}
445		if len(measurements) == 0 {
446			return Sample{}, ErrNoMeasurements
447		}
448		ms := make([]Measurement, len(measurements))
449		seen := make(map[string]float64, len(measurements))
450		for i, m := range measurements {
451			item := clean(m.Item)
452			if item == "" {
453				return Sample{}, ErrEmptyField
454			}
455			if !finite(m.Value) {
456				return Sample{}, ErrInvalidValue
457			}
458			if _, dup := seen[item]; dup {
459				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
460			}
461			seen[item] = m.Value
462			ms[i] = Measurement{Item: item, Value: m.Value}
463		}
464		sampledAt = sampledAt.UTC()
465	
466		if existing, ok := s.samples[id]; ok {
467			if sameSampleContent(existing, pointID, sampledAt, seen) {
468				return copySample(existing), nil
469			}
470			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
471		}
472		if _, ok := s.points[pointID]; !ok {
473			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
474		}
475		smp := &Sample{
476			ID:           id,
477			PointID:      pointID,
478			SampledAt:    sampledAt,
479			Measurements: ms,
480			Status:       StatusPending,
481		}
482		s.samples[id] = smp
483		if err := s.persistLocked(); err != nil {
484			delete(s.samples, id)
485			return Sample{}, err
486		}
487		return copySample(smp), nil
488	}
489	
490	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
491		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
492			return false
493		}
494		for _, m := range s.Measurements {
495			v, ok := ms[m.Item]
496			if !ok || v != m.Value {
497				return false
498			}
499		}
500		return true
501	}
502	
503	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
504	// 测量值大于上限才超标，任一项目超标则整份样品超标。
505	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
506	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
507	func (s *Store) Confirm(id string) (Sample, error) {
508		s.mu.Lock()
509		defer s.mu.Unlock()
510		if err := s.checkOpenLocked(); err != nil {
511			return Sample{}, err
512		}
513		id = clean(id)
514		if id == "" {
515			return Sample{}, ErrEmptyField
516		}
517		smp, ok := s.samples[id]
518		if !ok {
519			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
520		}
521		switch smp.Status {
522		case StatusVoided:
523			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
524		case StatusConfirmed:
525			return copySample(smp), nil
526		}
527	
528		results := make([]ItemResult, 0, len(smp.Measurements))
529		exceeded := false
530		for _, m := range smp.Measurements {
531			lim, ok := applicableLimit(s.limits[limitGroup{pointID: smp.PointID, item: m.Item}], smp.SampledAt)
532			if !ok {
533				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
534			}
535			ex := m.Value > lim.Value
536			if ex {
537				exceeded = true
538			}
539			results = append(results, ItemResult{
540				Item:           m.Item,
541				Value:          m.Value,
542				Limit:          lim.Value,
543				LimitEffective: lim.Effective,
544				Exceeded:       ex,
545			})
546		}
547		smp.Results = results
548		smp.Exceeded = exceeded
549		smp.Status = StatusConfirmed
550		if err := s.persistLocked(); err != nil {
551			smp.Results = nil
552			smp.Exceeded = false
553			smp.Status = StatusPending
554			return Sample{}, err
555		}
556		return copySample(smp), nil
557	}
558	
559	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
560	// 采样时间恰好等于生效时间时使用该版新值。
561	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
562		best := -1
563		for i, v := range versions {
564			if v.Effective.After(at) {
565				break
566			}
567			best = i
568		}
569		if best < 0 {
570			return Limit{}, false
571		}
572		return versions[best], true
573	}
574	
575	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
576	// 作废原因必须是合法的 UTF-8 文本：原始原因含孤立的 0xFF、0xFE 字节或不完整
577	// 的多字节序列等无法原样保存的内容时，本次作废整体以 ErrInvalidText 拒绝，
578	// 返回空样品，不删除或替换任何字节、不改动样品状态与已有原因；即使样品编号
579	// 不存在，或样品已作废而这次原因与原原因不同，也报告文本编码错误，而不是
580	// 样品不存在或原因冲突（数据存放已关闭时仍返回 ErrClosed）。真正的 U+FFFD
581	// （“�”）、中文、表情和文本内部的 U+0000 仍是合法字符。作废后保留测量、原因
582	// 和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
583	func (s *Store) Void(id, reason string) (Sample, error) {
584		s.mu.Lock()
585		defer s.mu.Unlock()
586		if err := s.checkOpenLocked(); err != nil {
587			return Sample{}, err
588		}
589		// 在去首尾空白、查找样品和比对原因等任何处理之前检查原始原因：落盘 JSON
590		// 会把非法 UTF-8 静默替换成 U+FFFD，作废“成功”后当场返回的原因仍带原始
591		// 字节，保存与重开后却变成替换字符，同一记录前后对不上，再次提交原原因
592		// 还会被误判成原因冲突；只有整次拒绝才能保证原因在保存前后一致。
593		if invalidUTF8(reason) {
594			return Sample{}, ErrInvalidText
595		}
596		id, reason = clean(id), clean(reason)
597		if id == "" || reason == "" {
598			return Sample{}, ErrEmptyField
599		}
600		smp, ok := s.samples[id]
601		if !ok {
602			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
603		}
604		if smp.Status == StatusVoided {
605			if smp.VoidReason == reason {
606				return copySample(smp), nil
607			}
608			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
609		}
610		oldStatus := smp.Status
611		smp.Status = StatusVoided
612		smp.VoidReason = reason
613		if err := s.persistLocked(); err != nil {
614			smp.Status = oldStatus
615			smp.VoidReason = ""
616			return Sample{}, err
617		}
618		return copySample(smp), nil
619	}
620	
621	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
622	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
623		s.mu.Lock()
624		defer s.mu.Unlock()
625		if err := s.checkOpenLocked(); err != nil {
626			return nil, err
627		}
628		return s.pointSamplesLocked(clean(pointID), func(*Sample) bool { return true }), nil
629	}
630	
631	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
632	// 没有已确认且未作废的样品时 ok 为 false。
633	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
634		s.mu.Lock()
635		defer s.mu.Unlock()
636		if err := s.checkOpenLocked(); err != nil {
637			return Sample{}, false, err
638		}
639		list := s.pointSamplesLocked(clean(pointID), func(smp *Sample) bool {
640			return smp.Status == StatusConfirmed
641		})
642		if len(list) == 0 {
643			return Sample{}, false, nil
644		}
645		return list[0], true, nil
646	}
647	
648	// pointSamplesLocked 收集某采样点符合 keep 的样品，逐份复制后按统一规则排列，
649	// 供 ListByPoint 与 LatestResult 共用，保证两种查询对同一批样品的先后判断一致。
650	// 调用方须已持有锁；pointID 须已做首尾空白处理。
651	func (s *Store) pointSamplesLocked(pointID string, keep func(*Sample) bool) []Sample {
652		var list []Sample
653		for _, smp := range s.samples {
654			if smp.PointID == pointID && keep(smp) {
655				list = append(list, copySample(smp))
656			}
657		}
658		sortSamples(list)
659		return list
660	}
661	
662	func sortSamples(list []Sample) {
663		sort.Slice(list, func(i, j int) bool {
664			a, b := list[i], list[j]
665			if !a.SampledAt.Equal(b.SampledAt) {
666				return a.SampledAt.After(b.SampledAt)
667			}
668			return a.ID < b.ID
669		})
670	}
671	
672	func copySample(s *Sample) Sample {
673		c := *s
674		c.Measurements = append([]Measurement(nil), s.Measurements...)
675		c.Results = append([]ItemResult(nil), s.Results...)
676		return c
677	}
678

