415	// 待判定样品没有判定记录、待判定后作废的样品没有历史依据，都仍是正常情况；
416	// 已确认后作废但历史依据完整的样品也继续兼容（列表可查、最近结果跳过、
417	// 再确认拒绝）。
418	func TestOpenPendingAndVoidedSamples(t *testing.T) {
419		dir := t.TempDir()
420		writeDiskFile(t, dir, diskState{
421			Points: map[string]SamplingPoint{
422				"P1": {ID: "P1", Name: "一号取水口"},
423				"P2": {ID: "P2", Name: "二号取水口"},
424			},
425			Samples: map[string]*Sample{
426				// 待判定：无判定记录。
427				"SP": {
428					ID: "SP", PointID: "P1", SampledAt: at(2, 0),
429					Measurements: []Measurement{{Item: openPH, Value: 9}},
430					Status:       StatusPending,
431				},
432				// 待判定后作废：无历史依据。
433				"SV": {
434					ID: "SV", PointID: "P1", SampledAt: at(3, 0),
435					Measurements: []Measurement{{Item: openPH, Value: 9}},
436					Status:       StatusVoided, VoidReason: "录入信息有误",
437				},
438				// 已确认后作废：历史依据完整。
439				"SCV": {
440					ID: "SCV", PointID: "P2", SampledAt: at(4, 0),
441					Measurements: []Measurement{{Item: openPH, Value: 9}},
442					Status:       StatusVoided, VoidReason: "复测确认样品污染", Exceeded: true,
443					Results: []ItemResult{
444						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
445					},
446				},
447			},
448		})
449		s, err := Open(dir)
450		if err != nil {
451			t.Fatalf("待判定与无历史依据的作废样品都应正常读入: %v", err)
452		}
453		defer s.Close()
454	
455		p1, err := s.ListByPoint("P1")
456		if err != nil || len(p1) != 2 {
457			t.Fatalf("P1 列表: %+v err=%v", p1, err)
458		}
459		byID := map[string]Sample{}
460		for _, smp := range p1 {
461			byID[smp.ID] = smp
462		}
463		sp := byID["SP"]
464		if sp.Status != StatusPending || sp.Results != nil || sp.Exceeded {
465			t.Fatalf("待判定样品读入后不应带结论: %+v", sp)
466		}
467		sv := byID["SV"]
468		if sv.Status != StatusVoided || sv.VoidReason != "录入信息有误" ||
469			len(sv.Results) != 0 || sv.Exceeded {
470			t.Fatalf("待判定后作废样品不应凭空获得结论: %+v", sv)
471		}
472		// P1 没有已确认且未作废的样品：明确无结果。
473		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
474			t.Fatalf("P1 应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
475		}
476	
477		// 已确认后作废的完整历史记录继续兼容。
478		p2, err := s.ListByPoint("P2")
479		if err != nil || len(p2) != 1 {
480			t.Fatalf("P2 列表: %+v err=%v", p2, err)
481		}
482		scv := p2[0]
483		if scv.Status != StatusVoided || !scv.Exceeded || len(scv.Results) != 1 {
484			t.Fatalf("已确认后作废的历史依据应保留: %+v", scv)
485		}
486		if r := scv.Results[0]; r.Item != openPH || r.Value != 9 || r.Limit != 8 ||
487			!r.LimitEffective.Equal(openEff()) || !r.Exceeded {
488			t.Fatalf("历史判定依据被改动: %+v", r)
489		}
490		if latest, ok, err := s.LatestResult("P2"); err != nil || ok {
491			t.Fatalf("作废样品不应作为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
492		}
493		if _, err := s.Confirm("SCV"); !errors.Is(err, ErrVoided) {
494			t.Fatalf("已作废样品再确认应被拒绝，got %v", err)
495		}
496	}
497	
498	// 已确认后作废但历史依据缺项，同样不能读入：作废只取消有效资格，
499	// 不能让对不上的结论借“历史记录”名义混进台账。
500	func TestOpenVoidedAfterConfirmedMissingItemResult(t *testing.T) {
501		dir := t.TempDir()
502		writeDiskFile(t, dir, diskState{
503			Points: openPoints(),
504			Samples: map[string]*Sample{
505				"S1": {
506					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
507					Measurements: phTurbMeasurements(),
508					Status:       StatusVoided, VoidReason: "作废", Exceeded: true,
509					Results: []ItemResult{
510						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
511					},
512				},
513			},
514		})
515		assertOpenRejects(t, dir, "S1", openTurb, false)
516	}
517	
518	// 文件里出现空样品记录（JSON null）时不能崩溃，也要整次失败并按 map 编号指出。
519	func TestOpenNullSampleRecord(t *testing.T) {
520		dir := t.TempDir()
521		writeDiskFile(t, dir, diskState{
522			Points: openPoints(),
523			Samples: map[string]*Sample{
524				"S1": nil,
525			},
526		})
527		assertOpenRejects(t, dir, "S1", "", true)
528	}
529	
530	// 待判定样品没有逐项判定不是损坏，但原测量里同一项目出现两次仍是损坏：
531	// 即使两条 pH 都是零，也必须在打开时整次失败并点名样品与项目，
532	// 不能等确认时才暴露，更不能把两条测量都当成判定依据。
533	func TestOpenPendingDuplicateMeasurement(t *testing.T) {
534		dir := t.TempDir()
535		writeDiskFile(t, dir, diskState{
536			Points: openPoints(),
537			Samples: map[string]*Sample{
538				"S1": {
539					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
540					Measurements: []Measurement{
541						{Item: openPH, Value: 0}, {Item: openPH, Value: 0},
542					},
543					Status: StatusPending,
544				},
545			},
546		})
547		assertOpenRejects(t, dir, "S1", openPH, false)
548	}
549	
550	// 待判定样品的重复项目不要求相邻：pH 中间隔着浊度，仍是同一份样品里的重复。
551	func TestOpenPendingDuplicateMeasurementNonAdjacent(t *testing.T) {
552		dir := t.TempDir()
553		writeDiskFile(t, dir, diskState{
554			Points: openPoints(),
555			Samples: map[string]*Sample{
556				"S1": {
557					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
558					Measurements: []Measurement{
559						{Item: openPH, Value: 9}, {Item: openTurb, Value: 4}, {Item: openPH, Value: 7},
560					},
561					Status: StatusPending,
562				},
563			},
564		})
565		assertOpenRejects(t, dir, "S1", openPH, false)
566	}
567	
568	// 待判定后直接作废、没有历史判定依据的样品同样不能带重复测量混入台账。
569	func TestOpenVoidedFromPendingDuplicateMeasurement(t *testing.T) {
570		dir := t.TempDir()
571		writeDiskFile(t, dir, diskState{
572			Points: openPoints(),
573			Samples: map[string]*Sample{
574				"S1": {
575					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
576					Measurements: []Measurement{
577						{Item: openPH, Value: 9}, {Item: openPH, Value: 9},
578					},
579					Status: StatusVoided, VoidReason: "录入信息有误",
580				},
581			},
582		})
583		assertOpenRejects(t, dir, "S1", openPH, false)
584	}
585	
586	// 不同项目碰巧测得相同的零值不是重复：待判定样品的 pH 与浊度都是零，
587	// 必须正常读入，且读入后仍是待判定、没有结论。
588	func TestOpenPendingDifferentItemsSameZero(t *testing.T) {
589		dir := t.TempDir()
590		writeDiskFile(t, dir, diskState{
591			Points: openPoints(),
592			Samples: map[string]*Sample{
593				"S1": {
594					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
595					Measurements: []Measurement{{Item: openPH, Value: 0}, {Item: openTurb, Value: 0}},
596					Status:       StatusPending,
597				},
598			},
599		})
600		s, err := Open(dir)
601		if err != nil {
602			t.Fatalf("不同项目同值（零）不是重复，待判定样品应正常读入: %v", err)
603		}
604		defer s.Close()
605		list, err := s.ListByPoint("P1")
606		if err != nil || len(list) != 1 {
607			t.Fatalf("ListByPoint: %+v err=%v", list, err)
608		}
609		smp := list[0]
610		if smp.Status != StatusPending || smp.Results != nil || smp.Exceeded {
611			t.Fatalf("待判定样品读入后不应带结论: %+v", smp)
612		}
613		ms := map[string]float64{}
614		for _, m := range smp.Measurements {
615			ms[m.Item] = m.Value
616		}
617		if len(ms) != 2 || ms[openPH] != 0 || ms[openTurb] != 0 {
618			t.Fatalf("两个不同项目的零测量值必须原样保留: %+v", smp.Measurements)
619		}
620	}
621	
622	// 同一项目出现在不同样品中是正常记录：两份待判定样品各有一条 pH，必须都读入。
623	func TestOpenSameItemAcrossDifferentSamples(t *testing.T) {
624		dir := t.TempDir()
625		writeDiskFile(t, dir, diskState{
626			Points: openPoints(),
627			Samples: map[string]*Sample{
628				"S1": {
629					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
630					Measurements: []Measurement{{Item: openPH, Value: 0}},
631					Status:       StatusPending,
632				},
633				"S2": {
634					ID: "S2", PointID: "P1", SampledAt: at(11, 0),
635					Measurements: []Measurement{{Item: openPH, Value: 0}},
636					Status:       StatusPending,
637				},
638			},
639		})
640		s, err := Open(dir)
641		if err != nil {
642			t.Fatalf("同一项目分属不同样品是正常记录: %v", err)
643		}
644		defer s.Close()
645		list, err := s.ListByPoint("P1")
646		if err != nil || len(list) != 2 {
647			t.Fatalf("两份样品都应读入: %+v err=%v", list, err)
648		}
649	}
650	
651	// 待判定的损坏样品与其他完整样品同处一个文件：不能只跳过它继续打开，
652	// 整次失败、无可用存放，完整样品也读不到。
653	func TestOpenPendingDuplicateRejectsWholeFile(t *testing.T) {
654		dir := t.TempDir()
655		writeDiskFile(t, dir, diskState{
656			Points: openPoints(),
657			Samples: map[string]*Sample{
658				// 完整、正常的已确认样品。
659				"S-GOOD": {
660					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
661					Measurements: []Measurement{{Item: openPH, Value: 7}},
662					Status:       StatusConfirmed, Exceeded: false,
663					Results: []ItemResult{
664						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
665					},
666				},
667				// 待判定但测量项目重复的损坏样品。
668				"S-BAD": {
669					ID: "S-BAD", PointID: "P1", SampledAt: at(10, 0),
670					Measurements: []Measurement{
671						{Item: openPH, Value: 0}, {Item: openPH, Value: 0},
672					},
673					Status: StatusPending,
674				},
675			},
676		})
677		assertOpenRejects(t, dir, "S-BAD", openPH, false)
678	}
